/* ================= STEP 2: character creation lab ================= */
#creator { position: absolute; inset: 0; z-index: 21; pointer-events: none; }
#creator > * { pointer-events: auto; }
#creatorDrag {
  position: absolute; top: 0; bottom: 96px; left: min(404px, 42vw); right: 0;
  cursor: grab; touch-action: none;
}
#creatorDrag:active { cursor: grabbing; }
#creatorHead {
  position: absolute; top: 10px; left: 12px; right: 12px;
  display: flex; flex-wrap: wrap; align-items: center; gap: 8px 14px;
  pointer-events: none;
}
#creatorHead button, #viewCtl button { pointer-events: auto; }
#creatorTitle {
  font-family: 'Rubik Glitch', Impact, sans-serif;
  font-size: clamp(20px, 3.2vw, 36px); color: var(--bone);
  text-shadow: 2px 2px 0 var(--blood), -1px -1px 0 #000;
  transform: rotate(-1.2deg);
}
#creatorSub { font-size: 10px; letter-spacing: 2px; color: #9a8f7a; }
#viewCtl { margin-left: auto; display: flex; align-items: center; gap: 6px; flex-wrap: wrap; }
#viewLbl { font-size: 10px; letter-spacing: 2px; color: #6a6056; }
.vbtn {
  font-family: 'Bebas Neue', Impact, sans-serif; font-size: 13px; letter-spacing: 1px;
  color: var(--bone); background: #17130f; border: 1px solid #3a322a;
  border-bottom: 3px solid #000; padding: 5px 10px; cursor: pointer;
  transition: background .1s, color .1s;
}
.vbtn:hover { color: var(--acid); border-color: var(--acid); }
#dragHint { font-size: 10px; color: #6a6056; letter-spacing: 1px; }

#creatorPanel {
  position: absolute; top: 60px; left: 12px; bottom: 96px;
  width: min(392px, 42vw); overflow-y: auto;
  background: linear-gradient(rgba(14,12,10,.93), rgba(8,7,6,.97));
  border: 1px solid #2c2620; border-left: 4px solid var(--acid);
  padding: 12px 12px 18px;
  scrollbar-width: thin; scrollbar-color: var(--blood) #111;
  background-image: repeating-linear-gradient(0deg, rgba(255,255,255,.012) 0 2px, transparent 2px 5px);
}
.secHead {
  font-family: 'Bebas Neue', Impact, sans-serif; font-size: 16px; letter-spacing: 3px;
  color: var(--acid); margin: 16px 0 6px;
  border-bottom: 1px dashed #3a322a; padding-bottom: 3px;
}
.secHead:first-child { margin-top: 0; }
.subHead { font-size: 10px; letter-spacing: 2px; color: #9a8f7a; margin: 10px 0 4px; }
.optGrid { display: grid; grid-template-columns: 1fr 1fr; gap: 6px; }
.optBtn {
  background: #14110e; border: 1px solid #2a241e; color: #b9ad96;
  font-family: 'Bebas Neue', Impact, sans-serif; font-size: 14px; letter-spacing: 1px;
  padding: 7px 8px 8px; cursor: pointer; text-align: left; line-height: 1.12;
  display: flex; flex-direction: column; gap: 3px;
  transition: background .1s, border-color .1s, transform .06s;
}
.optBtn small { font-family: 'Special Elite', 'Courier New', monospace; font-size: 9px; color: #776c5c; letter-spacing: 0; line-height: 1.3; }
.optBtn:hover { border-color: #6a5a44; transform: translateX(2px); }
.optBtn.sel {
  border-color: var(--acid); background: #1a1e10; color: var(--bone);
  box-shadow: 0 0 10px rgba(157,255,42,.14);
}
.optBtn.sel small { color: var(--acid); }
.optBtn .sw { width: 100%; height: 10px; border: 1px solid #000; }
.chipRow { display: flex; flex-wrap: wrap; gap: 5px; }
.chip {
  font-family: 'Bebas Neue', Impact, sans-serif; font-size: 12px; letter-spacing: 1px;
  color: #9a8f7a; background: #14110e; border: 1px solid #2a241e;
  padding: 5px 9px; cursor: pointer;
  transition: background .1s, color .1s;
}
.chip:hover { color: var(--bone); border-color: #6a5a44; }
.chip.sel { color: #0c0c0c; background: var(--acid); border-color: var(--acid); }

#creatorFoot {
  position: absolute; left: 12px; right: 12px; bottom: 10px;
  display: flex; align-items: center; gap: 10px; flex-wrap: wrap;
  background: linear-gradient(rgba(14,12,10,.92), rgba(8,7,6,.95));
  border: 1px solid #2c2620; border-right: 4px solid var(--blood);
  padding: 8px 10px;
}
#nameWrap { display: flex; gap: 6px; align-items: center; flex: 1; min-width: 210px; }
#ratName {
  flex: 1; min-width: 0; background: #0d0b09; border: 1px solid #3a322a;
  border-bottom: 3px solid var(--blood);
  color: var(--acid); font-family: 'Bebas Neue', Impact, sans-serif;
  font-size: 20px; letter-spacing: 2px; padding: 7px 10px;
  text-transform: uppercase; outline: none;
}
#ratName::placeholder { color: #5a5248; }
#ratName:focus { border-color: var(--acid); }
.rbtn.cbtn { font-size: 15px; padding: 8px 12px; }
.rbtn.acid {
  background: linear-gradient(#b8ff4a, #7ecc17); color: #0c0c0c;
  border-color: #5a8a10; font-size: 21px; padding: 10px 24px;
  text-shadow: none;
}
.rbtn.acid:hover { background: #ccff66; color: #000; }

@media (max-width: 760px) {
  #creatorPanel { width: auto; left: 8px; right: 8px; top: 88px; bottom: 148px; }
  #creatorDrag { left: 0; bottom: 148px; }
  #viewCtl { margin-left: 0; }
  #creatorFoot { padding: 6px; gap: 6px; }
  .rbtn.acid { font-size: 18px; padding: 8px 16px; }
}

